package com.motionstudio.part3
import kotlin.math.*
class GraphEditorPro{data class Point(val time:Double,val value:Double);fun valueCurve(track:KeyframeTrack<Double>,samples:Int=128):List<Point>{require(samples>=2);val k=track.all();if(k.isEmpty())return emptyList();val a=k.first().time;val b=k.last().time;return (0 until samples).map{val t=a+(b-a)*it/(samples-1.0);Point(t,track.evaluate(t)?:0.0)}};fun velocity(points:List<Point>):List<Point>{if(points.size<2)return emptyList();return points.zipWithNext().map{(a,b)->Point((a.time+b.time)/2,(b.value-a.value)/(b.time-a.time).coerceAtLeast(1e-12))}};fun normalize(points:List<Point>):List<Point>{if(points.isEmpty())return emptyList();val lo=points.minOf{it.value};val hi=points.maxOf{it.value};return points.map{it.copy(value=if(hi==lo).5 else (it.value-lo)/(hi-lo))}};fun snap(t:Double,grid:Double)=if(grid<=0)t else round(t/grid)*grid}
